const cfg = $('Config').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const pol = uniq($('Read Policy').all().map(i => i.json).filter(r => r && r.policy_key), 'policy_key');
const reps = uniq($('Read Reps').all().map(i => i.json).filter(r => r && r.rep_id), 'rep_id');
const outs = uniq($('Read Outlets').all().map(i => i.json).filter(r => r && r.outlet_id), 'outlet_id');
const recs = uniq($('Read Visit Records').all().map(i => i.json).filter(r => r && r.record_id), 'record_id');
const pipe = uniq($('Read Pipeline').all().map(i => i.json).filter(r => r && r.opp_id), 'opp_id');
const P = {};
pol.forEach(r => { P[String(r.policy_key).trim()] = r.policy_value; });
const cyc = { A: num(P.visit_cycle_days_A) || 7, B: num(P.visit_cycle_days_B) || 14, C: num(P.visit_cycle_days_C) || 30 };
const stuckDays = num(P.stuck_days) || 21;
const beatSize = num(P.beat_size) || 5;
const TZ = num(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + TZ * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const today = fd(now);
const tMs = Date.parse(today + 'T00:00:00Z');
const daysAgo = (ds) => { const t = Date.parse(String(ds || '').trim().slice(0, 10) + 'T00:00:00Z'); if (isNaN(t)) { return 999; } return Math.round((tMs - t) / 86400000); };
const issues = [];
if (outs.length === 0) { issues.push('No outlets found, the territory review is empty'); }
const repBy = {};
reps.forEach(r => { repBy[String(r.rep_id).trim()] = r; });
const elapsed = num(cfg.month_days_elapsed) || 26;
const totalDays = num(cfg.month_days_total) || 30;
const paceFactor = totalDays > 0 ? elapsed / totalDays : 1;
const overdue = [];
let covered = 0;
outs.forEach(o => {
  const tier = String(o.tier || 'C').toUpperCase().trim();
  const cycle = cyc[tier] || 30;
  const since = daysAgo(o.last_visit_date);
  const over = since - cycle;
  if (over <= 0) { covered += 1; return; }
  const potential = num(o.monthly_potential_inr);
  const current = num(o.current_monthly_inr);
  const gap = Math.max(0, potential - current);
  const tierW = tier === 'A' ? 3 : (tier === 'B' ? 2 : 1);
  const urgency = Math.round((over * tierW) + (gap / 10000));
  overdue.push({ outlet_id: String(o.outlet_id), name: String(o.name || ''), tier: tier, area: String(o.area || ''), owner_name: String(o.owner_name || ''),
    rep_id: String(o.rep_id || ''), days_since: since, cycle: cycle, days_over: over, potential: potential, current: current, gap: gap,
    status: String(o.status || 'active'), urgency: urgency });
});
overdue.sort((a, b) => b.urgency - a.urgency);
const coveragePct = outs.length > 0 ? Math.round((covered / outs.length) * 100) : 0;
const gapAtRisk = overdue.reduce((a, o) => a + o.gap, 0);
const stuck = [];
pipe.forEach(p => {
  const since = daysAgo(p.last_updated);
  const stage = String(p.stage || '').toLowerCase().trim();
  if (stage === 'active' || stage === 'at_risk') { return; }
  if (since < stuckDays) { return; }
  stuck.push({ opp_id: String(p.opp_id), outlet_name: String(p.outlet_name || ''), rep_id: String(p.rep_id || ''), stage: stage, value: num(p.value_inr), days_stuck: since });
});
stuck.sort((a, b) => b.value - a.value);
const stuckValue = stuck.reduce((a, s) => a + s.value, 0);
const compTally = {};
recs.forEach(r => { const c = String(r.competitor || 'none').trim(); if (c.toLowerCase() !== 'none' && c.length > 1) { compTally[c] = (compTally[c] || 0) + 1; } });
const compList = Object.keys(compTally).map(k => ({ name: k, mentions: compTally[k] }));
compList.sort((a, b) => b.mentions - a.mentions);
const repStats = [];
reps.forEach(r => {
  const rid = String(r.rep_id).trim();
  const target = num(r.monthly_target_inr);
  const mtd = num(r.mtd_sales_inr);
  const myRecs = recs.filter(x => String(x.rep_id || '').trim() === rid);
  const myOrders = myRecs.filter(x => num(x.order_value_inr) > 0);
  const myOrderValue = myOrders.reduce((a, x) => a + num(x.order_value_inr), 0);
  const myOutlets = outs.filter(x => String(x.rep_id || '').trim() === rid);
  const myOverdue = overdue.filter(x => x.rep_id === rid);
  const pct = target > 0 ? Math.round((mtd / target) * 100) : 0;
  const expected = Math.round(target * paceFactor);
  const behind = expected - mtd;
  const cov = myOutlets.length > 0 ? Math.round(((myOutlets.length - myOverdue.length) / myOutlets.length) * 100) : 0;
  const conv = myRecs.length > 0 ? Math.round((myOrders.length / myRecs.length) * 100) : 0;
  repStats.push({ rep_id: rid, name: String(r.name || ''), email: String(r.email || ''), territory: String(r.territory || ''),
    target: target, mtd: mtd, pct: pct, expected: expected, behind: behind, on_track: behind <= 0,
    outlets: myOutlets.length, overdue: myOverdue.length, coverage: cov,
    visits: myRecs.length, orders: myOrders.length, order_value: myOrderValue, conversion: conv,
    beat: myOverdue.slice(0, beatSize) });
});
repStats.sort((a, b) => a.pct - b.pct);
const totalTarget = repStats.reduce((a, r) => a + r.target, 0);
const totalMtd = repStats.reduce((a, r) => a + r.mtd, 0);
const teamPct = totalTarget > 0 ? Math.round((totalMtd / totalTarget) * 100) : 0;
let ctx = '';
ctx += 'DATE: ' + today + ', day ' + elapsed + ' of ' + totalDays + ' in the month\n';
ctx += 'TEAM: Rs ' + totalMtd + ' against a target of Rs ' + totalTarget + ', that is ' + teamPct + ' percent with ' + Math.round(paceFactor * 100) + ' percent of the month gone\n';
ctx += 'COVERAGE: ' + coveragePct + ' percent of outlets visited inside their tier cycle, ' + overdue.length + ' outlets overdue, Rs ' + gapAtRisk + ' of untapped monthly potential sitting in them\n\nREPS:\n';
repStats.forEach(r => { ctx += r.name + ' (' + r.territory + '): Rs ' + r.mtd + ' of Rs ' + r.target + ' (' + r.pct + ' percent), pace says they should be at Rs ' + r.expected + ', ' + (r.behind > 0 ? ('behind by Rs ' + r.behind) : 'ahead of pace') + '. Coverage ' + r.coverage + ' percent, ' + r.overdue + ' of ' + r.outlets + ' outlets overdue. ' + r.visits + ' visits logged, ' + r.orders + ' orders, ' + r.conversion + ' percent conversion.\n'; });
ctx += '\nWORST COVERAGE GAPS:\n';
overdue.slice(0, 8).forEach(o => { ctx += o.name + ' (tier ' + o.tier + ', ' + o.area + '): last visited ' + o.days_since + ' days ago against a ' + o.cycle + ' day cycle, ' + o.days_over + ' days over. Doing Rs ' + o.current + ' of Rs ' + o.potential + ' potential.\n'; });
ctx += '\nSTUCK PIPELINE:\n';
if (stuck.length === 0) { ctx += 'none\n'; }
stuck.forEach(s => { ctx += s.outlet_name + ': stuck at ' + s.stage + ' for ' + s.days_stuck + ' days, Rs ' + s.value + ' at stake\n'; });
ctx += '\nCOMPETITOR MENTIONS IN RECENT VISITS:\n';
if (compList.length === 0) { ctx += 'none\n'; }
compList.forEach(c => { ctx += c.name + ': named in ' + c.mentions + ' outlet(s)\n'; });
let beatBlob = '';
repStats.forEach(r => {
  if (r.beat.length === 0) { return; }
  beatBlob += '=== REP ' + r.rep_id + ' ' + r.name + ' (' + r.territory + ') ===\n';
  beatBlob += 'STATUS: Rs ' + r.mtd + ' of Rs ' + r.target + ' target, ' + r.pct + ' percent, ' + (r.behind > 0 ? ('behind pace by Rs ' + r.behind) : 'ahead of pace') + '\n';
  r.beat.forEach((o, i) => { beatBlob += (i + 1) + '. ' + o.name + ' (tier ' + o.tier + ', ' + o.area + '), owner ' + o.owner_name + ', last visited ' + o.days_since + ' days ago, ' + o.days_over + ' days over cycle, doing Rs ' + o.current + ' of Rs ' + o.potential + ' potential\n'; });
  beatBlob += '\n';
});
return [{ json: { today: today, company_name: cfg.company_name, manager_email: cfg.manager_email, manager_name: cfg.manager_name,
  send_beats: (String(cfg.send_beat_plans) === 'true') || (cfg.send_beat_plans === true),
  outlets_total: outs.length, covered: covered, coverage_pct: coveragePct, overdue: overdue, overdue_count: overdue.length, gap_at_risk: gapAtRisk,
  stuck: stuck, stuck_count: stuck.length, stuck_value: stuckValue, competitors: compList,
  reps: repStats, team_target: totalTarget, team_mtd: totalMtd, team_pct: teamPct, pace_pct: Math.round(paceFactor * 100),
  visits_logged: recs.length, context: ctx, beat_blob: beatBlob || 'none', data_issues: issues } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const T = $('Territory Engine').first().json;
if (!T.send_beats) { return []; }
const parsed = parseJson(textOf($input.first().json)) || {};
const plans = Array.isArray(parsed.plans) ? parsed.plans : [];
const planBy = {};
plans.forEach(p => { planBy[String(p.rep_id || '').trim()] = p; });
const SLATE = '#132A3A', AMBER = '#D98324', CREAM = '#FBF8F1', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A', GREEN = '#1B7E42', RED = '#C0392B';
const out = [];
(Array.isArray(T.reps) ? T.reps : []).forEach(r => {
  if (!r.email || r.beat.length === 0) { return; }
  const p = planBy[r.rep_id] || {};
  const stops = Array.isArray(p.stops) ? p.stops : [];
  const stopBy = {};
  stops.forEach(s => { stopBy[String(s.outlet_name || '').trim()] = String(s.why || ''); });
  const opening = p.opening_line || (r.behind > 0 ? ('You are Rs ' + r.behind + ' behind pace with ' + (100 - T.pace_pct) + ' percent of the month left.') : 'You are ahead of pace, keep the coverage tight.');
  const closing = p.closing_push || ('These ' + r.beat.length + ' outlets hold Rs ' + r.beat.reduce((a, o) => a + o.gap, 0) + ' of untapped monthly business.');
  let rows = '';
  r.beat.forEach((o, i) => {
    const why = stopBy[o.name] || (o.days_over + ' days past the ' + o.cycle + ' day cycle, doing Rs ' + o.current + ' of Rs ' + o.potential + ' potential.');
    const tcol = o.tier === 'A' ? RED : (o.tier === 'B' ? AMBER : GREY);
    rows += '<tr><td style="padding:0 26px 11px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E8E2D6;border-radius:8px;border-left:4px solid ' + tcol + ';background:#FFFFFF;"><tr><td style="padding:13px 15px;">' +
    '<table width="100%" cellpadding="0" cellspacing="0"><tr><td><div style="font-family:Georgia,serif;font-size:16px;font-weight:bold;color:' + SLATE + ';">' + (i + 1) + '. ' + esc(o.name) + '</div>' +
    '<div style="font-size:12px;color:' + GREY + ';margin-top:3px;">' + esc(o.owner_name) + ' &middot; ' + esc(o.area) + ' &middot; tier ' + esc(o.tier) + '</div></td>' +
    '<td align="right"><div style="display:inline-block;background:' + tcol + ';color:#FFFFFF;font-size:10.5px;font-weight:bold;padding:4px 9px;border-radius:4px;">' + esc(o.days_over) + 'd OVERDUE</div></td></tr></table>' +
    '<div style="font-size:13px;color:' + INK + ';line-height:1.5;margin-top:8px;">' + esc(why) + '</div>' +
    '<div style="font-size:11.5px;color:' + GREY + ';margin-top:6px;">Last visit ' + esc(o.days_since) + ' days ago &middot; doing Rs ' + esc(o.current) + ' of Rs ' + esc(o.potential) + ' &middot; Rs ' + esc(o.gap) + ' untapped</div>' +
    '</td></tr></table></td></tr>';
  });
  const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:620px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
  '<tr><td style="background:' + SLATE + ';padding:22px 26px;"><div style="color:' + AMBER + ';font-size:11px;font-weight:bold;letter-spacing:3px;">YOUR BEAT PLAN</div>' +
  '<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:23px;font-weight:bold;margin-top:6px;">' + esc(r.name) + '</div>' +
  '<div style="color:#9FB3C4;font-size:12.5px;margin-top:4px;">' + esc(r.territory) + ' &middot; ' + esc(T.today) + ' &middot; ' + esc(r.beat.length) + ' stops today</div></td></tr>' +
  '<tr><td style="padding:18px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
  '<td align="center" style="background:' + (r.on_track ? GREEN : RED) + ';border-radius:6px;padding:13px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:22px;font-weight:bold;">' + esc(r.pct) + '%</div><div style="color:#F0F0F0;font-size:10px;">of target</div></td><td width="7"></td>' +
  '<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:13px 6px;"><div style="color:' + SLATE + ';font-family:Georgia,serif;font-size:17px;font-weight:bold;">Rs ' + esc(r.mtd) + '</div><div style="color:' + GREY + ';font-size:10px;">this month</div></td><td width="7"></td>' +
  '<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:13px 6px;"><div style="color:' + SLATE + ';font-family:Georgia,serif;font-size:22px;font-weight:bold;">' + esc(r.coverage) + '%</div><div style="color:' + GREY + ';font-size:10px;">coverage</div></td><td width="7"></td>' +
  '<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:13px 6px;"><div style="color:' + SLATE + ';font-family:Georgia,serif;font-size:22px;font-weight:bold;">' + esc(r.overdue) + '</div><div style="color:' + GREY + ';font-size:10px;">outlets overdue</div></td>' +
  '</tr></table></td></tr>' +
  '<tr><td style="padding:16px 26px 12px 26px;"><div style="background:' + CREAM + ';border-radius:8px;padding:14px 16px;border-left:4px solid ' + AMBER + ';"><div style="font-size:14.5px;color:' + INK + ';line-height:1.55;">' + esc(opening) + '</div></div></td></tr>' +
  '<tr><td style="padding:4px 26px 10px 26px;"><div style="font-family:Georgia,serif;font-size:16px;font-weight:bold;color:' + SLATE + ';">Where to go today</div></td></tr>' + rows +
  '<tr><td style="padding:8px 26px 20px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:' + SLATE + ';border-radius:8px;"><tr><td style="padding:15px 18px;"><div style="color:#FFFFFF;font-size:14px;line-height:1.5;">' + esc(closing) + '</div></td></tr></table></td></tr>' +
  '<tr><td style="background:' + SLATE + ';padding:12px 26px;"><div style="color:#7E92A3;font-size:11px;">' + esc(T.company_name) + ' &middot; Field Sales Tracker &middot; Powered by Haus of Intelligence</div></td></tr>' +
  '</table></div>';
  out.push({ json: { to: r.email, subject: 'Your beat plan for ' + T.today + ', ' + r.beat.length + ' stops', html: html, rep_id: r.rep_id, rep_name: r.name, stops: r.beat.length, written_ok: !!p.opening_line } });
});
return out;

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const T = $('Territory Engine').first().json;
const a = parseJson(textOf($input.first().json)) || {};
const aiOk = !!a.headline;
const SLATE = '#132A3A', AMBER = '#D98324', CREAM = '#FBF8F1', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A', GREEN = '#1B7E42', RED = '#C0392B';
const issues = Array.isArray(T.data_issues) ? T.data_issues.slice(0) : [];
if (!aiOk) { issues.push('Territory analyst AI was unavailable, showing the computed numbers only'); }
let banner = '';
if (issues.length) { banner = '<tr><td style="padding:12px 26px 0 26px;"><div style="background:#FBE9E7;border-left:4px solid ' + RED + ';border-radius:6px;padding:11px 13px;font-size:12.5px;color:#7A1F14;"><strong>Heads up.</strong> ' + esc(issues.slice(0, 3).join('; ')) + '</div></td></tr>'; }
const headline = a.headline || (T.overdue_count + ' outlets overdue, Rs ' + T.gap_at_risk + ' of potential sitting untouched');
const theRead = a.the_read || 'Review the numbers below.';
let repHtml = '';
(Array.isArray(T.reps) ? T.reps : []).forEach(r => {
  const col = r.pct >= 85 ? GREEN : (r.pct >= 60 ? AMBER : RED);
  repHtml += '<tr><td style="padding:0 26px 11px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E8E2D6;border-radius:8px;border-left:4px solid ' + col + ';background:#FFFFFF;"><tr><td style="padding:13px 15px;">' +
  '<table width="100%" cellpadding="0" cellspacing="0"><tr><td><div style="font-family:Georgia,serif;font-size:16.5px;font-weight:bold;color:' + SLATE + ';">' + esc(r.name) + '</div><div style="font-size:12px;color:' + GREY + ';margin-top:3px;">' + esc(r.territory) + ' &middot; ' + esc(r.outlets) + ' outlets</div></td>' +
  '<td align="right"><div style="font-family:Georgia,serif;font-size:24px;font-weight:bold;color:' + col + ';">' + esc(r.pct) + '%</div><div style="font-size:11px;color:' + GREY + ';">Rs ' + esc(r.mtd) + ' of ' + esc(r.target) + '</div></td></tr></table>' +
  '<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:9px;"><tr>' +
  '<td style="font-size:12px;color:' + INK + ';">coverage ' + esc(r.coverage) + '%</td>' +
  '<td style="font-size:12px;color:' + INK + ';">' + esc(r.overdue) + ' overdue</td>' +
  '<td style="font-size:12px;color:' + INK + ';">' + esc(r.visits) + ' visits</td>' +
  '<td style="font-size:12px;color:' + INK + ';">' + esc(r.conversion) + '% converted</td>' +
  '</tr></table>' +
  '<div style="font-size:12px;color:' + (r.on_track ? GREEN : RED) + ';margin-top:7px;">' + (r.behind > 0 ? ('Behind pace by Rs ' + esc(r.behind) + ', should be at Rs ' + esc(r.expected) + ' by now') : 'Ahead of pace') + '</div>' +
  '</td></tr></table></td></tr>';
});
let odHtml = '';
(Array.isArray(T.overdue) ? T.overdue : []).slice(0, 8).forEach(o => {
  const tcol = o.tier === 'A' ? RED : (o.tier === 'B' ? AMBER : GREY);
  odHtml += '<tr><td style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:13px;color:' + INK + ';"><strong>' + esc(o.name) + '</strong><br><span style="color:' + GREY + ';font-size:11px;">' + esc(o.area) + ' &middot; tier ' + esc(o.tier) + '</span></td>' +
  '<td align="center" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:14px;font-weight:bold;color:' + tcol + ';">' + esc(o.days_over) + 'd over</td>' +
  '<td align="right" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:12.5px;color:' + INK + ';">Rs ' + esc(o.gap) + '<br><span style="color:' + GREY + ';font-size:11px;">untapped</span></td></tr>';
});
let stHtml = '';
(Array.isArray(T.stuck) ? T.stuck : []).forEach(s => {
  stHtml += '<tr><td style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:13px;color:' + INK + ';"><strong>' + esc(s.outlet_name) + '</strong><br><span style="color:' + GREY + ';font-size:11px;">stuck at ' + esc(s.stage) + '</span></td>' +
  '<td align="center" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:14px;font-weight:bold;color:' + RED + ';">' + esc(s.days_stuck) + ' days</td>' +
  '<td align="right" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:13px;font-weight:bold;color:' + INK + ';">Rs ' + esc(s.value) + '</td></tr>';
});
let cpHtml = '';
(Array.isArray(T.competitors) ? T.competitors : []).forEach(c => {
  const hot = c.mentions >= 2;
  cpHtml += '<tr><td style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:13px;color:' + INK + ';"><strong>' + esc(c.name) + '</strong></td><td align="right" style="padding:9px 12px;border-bottom:1px solid #E8E2D6;font-size:14px;font-weight:bold;color:' + (hot ? RED : GREY) + ';">' + esc(c.mentions) + ' outlet(s)' + (hot ? ', a pattern' : '') + '</td></tr>';
});
let causeHtml = '';
(Array.isArray(a.root_causes) ? a.root_causes : []).forEach(c => {
  causeHtml += '<tr><td style="padding:0 26px 10px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E8E2D6;border-radius:8px;border-left:4px solid ' + AMBER + ';background:#FFFFFF;"><tr><td style="padding:13px 15px;"><div style="font-size:15px;font-weight:bold;color:' + SLATE + ';">' + esc(c.cause) + '</div><div style="font-size:12.5px;color:' + GREY + ';margin-top:5px;line-height:1.5;">' + esc(c.evidence) + '</div></td></tr></table></td></tr>';
